import {React , useState , useEffect} from 'react';
import Header from '../Utitlities/Header.js'
import ScrollToTop from '../Utitlities/ScrollToTop.js';
import PhoneInput from '../CustomComponents/PhoneInput.js'
import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';
import { Watch } from 'react-loader-spinner';
import axios from 'axios';
import { Store } from 'react-notifications-component';

const TsahelPage = () => {

    const [authenticated, setAuthenticated] = useState(false);
    const [nfathCode, setNfathCode] = useState(null);
    const [nafathSigned, setNafathSigned] = useState(false);
    const [showNafathPopup, setShowNafathPopup] = useState(false);
    const [nafathInterval, setNafathInterval] = useState(null);
    const [showContractPopup, setShowContractPopup] = useState(false);
    const [contractPdfUrl, setContractPdfUrl] = useState(null);
    const [showPdfPopup, setShowPdfPopup] = useState(false);
    const [pdfUrl, setPdfUrl] = useState(null);
    const [isMobile, setIsMobile] = useState(false);

    const { t } = useTranslation(['common']);
    const location = useLocation()
    const [lang, setLang] = useState((new URLSearchParams(location.search)).get('lang')??'ar')
    const [contractType, setContractType] = useState("1");

    useEffect(()=>{
        const userAgent = navigator.userAgent.toLowerCase();
        if (/mobile|android|iphone|ipad|ipod/i.test(userAgent)) {
            setIsMobile(true);
            console.log('Mobile device detected');
        }else {
            setIsMobile(false);
            console.log('Desktop device detected');
        }
    },[])



    useEffect(()=>{
        const lan = (new URLSearchParams(location.search)).get('lang')
        if(lan)setLang(lan)
    },[location.search])

    useEffect(()=>{
        document.getElementsByTagName('html')[0].style.direction = lang =='ar' ? 'rtl' :'ltr';
        document.getElementsByTagName('title')[0].innerHTML = lang == 'ar' ? 'بوابة تساهيل': 'Portal logistic';
    },[lang])

    const [formData, setFormData] = useState({
        first_name: "",
        father_name: "",
        grandfather_name: "",
        family_name: "",
        national_id: "",
        birth_date: "",
        phone: "",
        email: "",
        region: "",
        amount: "",
        type: 1,
    });

    async function fillContractWithClientData() {
        setLoading(true);
        setErrors({});
        try {
            const form = new FormData();
            Object.entries(formData).forEach(([key, value]) => {
                form.append(key, value);
            });

            const response = await fetch('https://shellafood.com/api/v1/portallogistice/contract-pdf', {
                method: 'POST',
                body: form
            });

            if (!response.ok) throw new Error('Failed to fetch contract HTML');
            const blob = await response.blob();
            const url = URL.createObjectURL(blob);
            setContractPdfUrl(url);
            setShowContractPopup(true);
            setLoading(false);
        } catch (e) {
            setErrors(prev => ({
                ...prev,
                contractPdf: 'حدث خطأ أثناء تحميل ملف العقد'
            }));
            setLoading(false);
        }
    }

    async function openPdfDraft() {
        setLoading(true);
        setErrors({});
        try {
            const form = new FormData();
            form.append('type', contractType);
            const response = await fetch('https://shellafood.com/api/v1/portallogistice/contract-pdf?pdf=1', {
                method: 'POST',
                body: form
            });
            console.log(response)
            if (!response.ok) throw new Error('Failed to fetch contract PDF');
            const blob = await response.blob();
            const url = URL.createObjectURL(blob);
            setPdfUrl(url);
            setShowPdfPopup(true);
        } catch (e) {
            setErrors(prev => ({
                ...prev,
                contractPdf: 'حدث خطأ أثناء تحميل ملف العقد PDF'
            }));
        } finally {
            setLoading(false);
        }
    }

    async function openPdfDraft2() {
        setLoading(true);
        setErrors({});
        try {
            const form = new FormData();
            form.append('type', contractType);

            const response = await fetch('https://shellafood.com/api/v1/portallogistice/contract-pdf?pdf=1', {
                method: 'POST',
                body: form
            });

            if (!response.ok) throw new Error('Failed to fetch contract PDF');
            const blob = await response.blob();
            const url = URL.createObjectURL(blob);
            setPdfUrl(url);
        } catch (e) {
            setErrors(prev => ({
                ...prev,
                contractPdf: 'حدث خطأ أثناء تحميل ملف العقد PDF'
            }));
        } finally {
            setLoading(false);
        }
    }

    async function openPdfInNewTab(isContract) {
        if(isContract){
            if(contractPdfUrl) {
                window.open(contractPdfUrl, '_blank', 'noopener,noreferrer');
            }
        }else {
            await openPdfDraft2().then(()=>{
                if (pdfUrl) {
                    window.open(pdfUrl, '_blank', 'noopener,noreferrer');
                }
            });
        }
    }   

    const [isAgreed, setIsAgreed] = useState(false);
    const [errors, setErrors] = useState({});
    const [loading , setLoading] = useState(false)
    const [confirmPassword, setConfirmPassword] = useState()


    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormDataValue(name,value);
    };

    const setFormDataValue = (name, value)=>{
        setFormData((prevData) => ({ ...prevData, [name]: value }));
    }

    const MobileInputValueChanged = (name,value)=>setFormDataValue(name,value)

    const validateForm = () => {
        let isValid = true;
        let newErrors = {};

        if (!formData.first_name) {
            newErrors.first_name = t('store_name_required');
            isValid = false;
        }
        if (!formData.father_name) {
            newErrors.father_name = t('father_name') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.grandfather_name) {
            newErrors.grandfather_name = t('grandfather_name') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.family_name) {
            newErrors.family_name = t('family_name') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.national_id) {
            newErrors.national_id = t('national_id') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.birth_date) {
            newErrors.birth_date = t('birth_date') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.phone) {
            newErrors.phone = t('phone_number') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.email) {
            newErrors.email = t('email') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.region) {
            newErrors.region = t('region') + ' ' + t('store_name_required');
            isValid = false;
        }
        if (!formData.amount) {
            newErrors.amount = t('amount') + ' ' + t('store_name_required');
            isValid = false;
        }
        if(formData.password != confirmPassword){
            newErrors.confirmPassword = t('passored-isnt-identical');
            isValid = false;
        }
        if (!isAgreed) {
            newErrors.isAgreed = t('agree_terms_alert') || 'You must agree to the terms and conditions';
            isValid = false;
        }

        setErrors(newErrors);
        return isValid;
    };

    const getFormData = (data)=>{
        const newForm = new FormData();

        Object.keys(data).forEach((key) => {
            if (data[key]) {
                newForm.append(key,data[key])
            }
        });

        return newForm
    }

    const handleSubmit = (e) => {
        e.preventDefault();

        if (!isAgreed) {
            alert(t('agree_terms_alert'));
            return;
        }

        if (validateForm()) {
            try {
                setLoading(true)
                axios.post('https://shellafood.com/api/v1/portallogistice/register', getFormData(formData) ,{ headers: {'Content-Type': 'multipart/form-data','X-LANG':lang}})
                .then(response=>{
                    if(response?.data?.errors)response?.data?.errors.forEach(ee=>setErrors((pe)=>({...pe,[ee.code]:ee.message})))
                    else handleReset();
                }).finally((a)=>setLoading(false))
            } catch (error) {
                setLoading(false)
                 throw error;
            }
        }
    };

    const handleReset = () => {
        setFormData({
            first_name: "",
            father_name: "",
            grandfather_name: "",
            family_name: "",
            national_id: "",
            birth_date: "",
            phone: "",
            email: "",
            region: "",
            amount: "",
            type:contractType
            
        });
        setErrors({});
        setIsAgreed(false);
    };

    const initiateNafath = async () => {
        if (!validateForm()) return;
        setLoading(true);
        setErrors({});
        try {
            const response = await axios.post('https://shellafood.com/api/v1/portallogistice/nafath/initiate', {
                national_id: formData.national_id,
                is_refresh: nfathCode ? true : false
            }, {
                headers: {
                    'Content-Type': 'application/json',
                    'X-LANG': lang
                }
            });
            const data = response?.data;
            if (data != null && data?.status === "sent" && data?.external_response && data?.external_response?.[0].error == "Success" && data?.external_response?.[0].random) {
                setNfathCode(data.external_response?.[0].random);
                setAuthenticated(true);
            } else {
                setErrors(prev => ({
                    ...prev,
                    nafathInitiation: data.message || 'Nafath initiation failed'
                }));
                setAuthenticated(false);
            }
        } catch (e) {
            if (e.response && e.response?.data && e.response?.data?.errors) {
                setErrors(prev => ({
                    ...prev,
                        nafathInitiation: e.response?.data?.message
                }));
            } else {
                setErrors(prev => ({
                    ...prev,
                    nafathInitiation: 'Nafath initiation failed'
                }));
            }
            setAuthenticated(false);
        }
        setLoading(false);
    };

    const checkNafathStatus = async () => {
        setErrors({});
        try {
            const response = await axios.post('https://shellafood.com/api/v1/portallogistice/nafath/checkStatus', {
                national_id: formData.national_id
            }, {
                headers: {
                    'Content-Type': 'application/json',
                    'X-LANG': lang
                }
            });
            const data = response?.data;
            if(response.status==404){
                setNfathCode(null);
                setErrors(prev => ({
                    ...prev,
                    nafathInitiation: data?.message || 'Nafath request not found'
                }))
            }
            else{
                if (data.status === "approved") {
                    console.log('approved')
                    setShowNafathPopup(false);
                    setShowContractPopup(false)
                    setShowPdfPopup(false)
                    setNafathSigned(true);
                    setNfathCode(null)
                    handleReset();

                    Store.addNotification({
                      title: t('success'),
                      message: t('nafath_approved'),
                      type: "success",
                      insert: "top",
                      container: "top-right",
                      animationIn: ["animate__animated", "animate__fadeIn"],
                      animationOut: ["animate__animated", "animate__fadeOut"],
                      dismiss: {
                        duration: 5000,
                        onScreen: true
                      }
                    });
                }else{
                    console.log('none')
                }
            }

            return data.status;
        } catch (e) {
            setErrors(prev => ({
                ...prev,
                nafathInitiation: e.response?.data?.message
            }));
            return null;
        }
    };

    useEffect(() => {
        let intervalId;
        if (nfathCode && !nafathSigned && formData.national_id) {
            setShowNafathPopup(true);
            intervalId = setInterval(async () => {
                try {
                    const status = await checkNafathStatus();
                    if (status === "approved") {
                        setShowNafathPopup(false);
                        setNafathSigned(true);
                        clearInterval(intervalId);
                    }
                } catch (e) {
                    setErrors(prev => ({
                        ...prev,
                        nafath: 'Nafath status check failed'
                    }));
                    clearInterval(intervalId);
                }
            }, 5000);
            setNafathInterval(intervalId);
        }
        return () => {
            if (intervalId) clearInterval(intervalId);
        };
    }, [nfathCode, nafathSigned]);

    useEffect(() => {
        return () => {
            if (nafathInterval) clearInterval(nafathInterval);
        };
    }, [nafathInterval]);

    useEffect(() => {
        if (errors.nafathInitiation) {
            const timer = setTimeout(() => {
                setErrors(prev => ({ ...prev, nafathInitiation: undefined }));
            }, 5000);
            return () => clearTimeout(timer);
        }
    }, [errors.nafathInitiation]);
  return (
        <section className="join-as-driver mb-4">
            {errors.nafathInitiation && (
                <div style={{
                    position: 'fixed',
                    top: 30,
                    left: '50%',
                    transform: 'translateX(-50%)',
                    zIndex: 999999,
                    background: '#ffeaea',
                    color: ' #d32f2f',
                    border: '1px solid #f5c2c7',
                    borderRadius: '8px',
                    padding: '12px 24px',
                    fontWeight: 600,
                    fontSize: '1rem',
                    boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
                }}>
                    {errors.nafathInitiation}
                </div>
            )}
            {loading ? (
                <div className='position-fixed w-100 h-100 top-0 start-0 d-flex flex-column'
                    style={{
                        background:'rgba(255,255,255,0.8)',
                        zIndex: 99999
                    }}>
                    <div className="d-flex justify-content-center m-auto w-100 h-100">
                        <Watch
                            visible={true}
                            height="80"
                            width="80"
                            radius="48"
                            color="#073491"
                            ariaLabel="watch-loading"
                            wrapperStyle={{}}
                            wrapperClass="m-auto d-flex justify-content-center"
                        />
                    </div>
                </div>
            ) : null}
            {showContractPopup && (
                <div style={{
                    position: 'fixed',
                    top: 0, left: 0, right: 0, bottom: 0,
                    background: 'rgba(0,0,0,0.4)',
                    zIndex: 3000,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                }}>
                    <div style={{
                        background: '#fff',
                        borderRadius: 12,
                        padding: '1.5rem 1.5rem 1rem 1.5rem',
                        boxShadow: '0 2px 16px rgba(0,0,0,0.15)',
                        minWidth: 350,
                        maxWidth: 800,
                        width: '90vw',
                        maxHeight: '90vh',
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        position: 'relative'
                    }}>
                        {nfathCode ? (
                            <>
                                <h3 style={{color:' #073491', marginBottom: 16}}>{t('nafath_code_title')}</h3>
                                <div style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    marginBottom: 12
                                }}>
                                    <span style={{
                                        display: 'inline-flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        width: 80,
                                        height: 80,
                                        borderRadius: '50%',
                                        border: '3px solid #073491',
                                        background: '#f7faf7',
                                        fontSize: 32,
                                        fontWeight: 'bold',
                                        letterSpacing: 4,
                                        color: '#222'
                                    }}>
                                        {nfathCode}
                                    </span>
                                </div>
                                <div style={{color:'#888', fontSize:15, marginBottom: 8}}>
                                    {t('nafath_code_desc')}
                                </div>
                                <div style={{display: 'flex', gap: 12, marginBottom: 8}}>
                                    <button
                                        type="button"
                                        className="btn btn-outline-danger"
                                        style={{minWidth: 100}}
                                        onClick={() => {
                                            setShowContractPopup(false);
                                            setNfathCode(null);
                                        }}
                                    >
                                        {t('cancel')}
                                    </button>
                                    {/* <button
                                        type="button"
                                        className="btn btn-outline-success"
                                        style={{minWidth: 100}}
                                        onClick={async () => {
                                            await initiateNafath();
                                        }}
                                    >
                                        {t('request_new_code')}
                                    </button> */}
                                </div>
                            </>
                        ) : (
                            <>
                                <div className={isMobile?'d-flex flex-column':''} style={{width: '100%', display: 'flex', justifyContent: 'center', gap: 12, marginBottom: 16}}>
                                    {(() => {
                                        let isValid = true;
                                        if (
                                            !formData.first_name ||
                                            !formData.father_name ||
                                            !formData.grandfather_name ||
                                            !formData.family_name ||
                                            !formData.national_id ||
                                            !formData.birth_date ||
                                            !formData.phone ||
                                            !formData.email ||
                                            !formData.region ||
                                            !formData.amount
                                        ) {
                                            isValid = false;
                                        }
                                        if (isValid) {
                                            return (
                                                <>
                                                    <button
                                                        type="button"
                                                        className="btn btn-submit"
                                                        style={{minWidth: 120}}
                                                        onClick={initiateNafath}
                                                    >
                                                        {t('nafath_authenticate')}
                                                    </button>
                                                    <button
                                                        type="button"
                                                        className="btn btn-outline-danger"
                                                        style={{minWidth: 120}}
                                                        onClick={() => {
                                                            setShowContractPopup(false);
                                                        }}
                                                    >
                                                        {t('edit_data')}
                                                    </button>
                                                    {
                                                        isMobile ? (
                                                            <button
                                                                type="button"
                                                                className="btn btn-outline-success"
                                                                style={{minWidth: 120}}
                                                                onClick={() => {
                                                                    openPdfInNewTab(true);
                                                                }}
                                                            >
                                                                {t('download-contract')}
                                                            </button>
                                                        ):null
                                                    }
                                                </>
                                            );
                                        } else {
                                            return (
                                                <>
                                                <button
                                                    type="button"
                                                    className="btn btn-outline-danger"
                                                    style={{minWidth: 120}}
                                                    onClick={() => {
                                                        setShowContractPopup(false);
                                                    }}
                                                >
                                                    {t('complete_data')}
                                                </button>
                                                {
                                                    isMobile ? (
                                                        <button
                                                            type="button"
                                                            className="btn btn-outline-success"
                                                            style={{minWidth: 120}}
                                                            onClick={() => {
                                                                openPdfInNewTab(true);
                                                            }}
                                                        >
                                                            {t('download-contract')}
                                                        </button>
                                                    ):null
                                                }
                                                </>
                                            );
                                        }
                                    })()}
                                </div>
                                {
                                    isMobile?null:(
                                        <div style={{
                                            width: '100%',
                                            height: '70vh',
                                            maxHeight: 600,
                                            marginBottom: 12,
                                            border: '2px solid #073491',
                                            borderRadius: 12,
                                            overflow: 'auto',
                                            background: '#fafafa',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            boxShadow: '0 2px 12px rgba(56,142,60,0.08)'
                                        }}>
                                            {contractPdfUrl ? (
                                                <embed
                                                    src={contractPdfUrl}
                                                    type="application/pdf"
                                                    width="100%"
                                                    height="600px"
                                                    style={{border: 'none', borderRadius: 8, marginTop: 20}}
                                                />
                                            ) : (
                                                <div style={{textAlign: 'center', padding: '2rem'}}>{t('contract_loading')}</div>
                                            )}
                                        </div>
                                    )
                                }

                            </>
                        )}
                    </div>
                </div>
            )}
            {showPdfPopup && (
                <div style={{
                    position: 'fixed',
                    top: 0, left: 0, right: 0, bottom: 0,
                    background: 'rgba(0,0,0,0.4)',
                    zIndex: 4000,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                }}>
                    <div style={{
                        background: '#fff',
                        borderRadius: 12,
                        padding: '1.5rem 1.5rem 1rem 1.5rem',
                        boxShadow: '0 2px 16px rgba(0,0,0,0.15)',
                        minWidth: 350,
                        maxWidth: 900,
                        width: '95vw',
                        maxHeight: '90vh',
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        position: 'relative'
                    }}>
                        <button
                            type="button"
                            className="btn btn-outline-danger"
                            style={{ minWidth: 80}}
                            onClick={() => {
                                setShowPdfPopup(false);
                                if (pdfUrl) {
                                    URL.revokeObjectURL(pdfUrl);
                                    setPdfUrl(null);
                                }
                            }}
                        >
                            {t('close')}
                        </button>
                        {pdfUrl ? (
                            <embed
                                src={pdfUrl}
                                type="application/pdf"
                                width="100%"
                                height="600px"
                                style={{border: 'none', borderRadius: 8, marginTop: 20}}
                            />
                        ) : (
                            <div style={{textAlign: 'center', padding: '2rem'}}>جارٍ تحميل ملف العقد...</div>
                        )}
                    </div>
                </div>
            )}
            <Header />
            <div className="join-as-driver-container">
                <div className="join-as-driver-main-content">
                    <div className="join-as-driver-form-title">
                        <h1>{lang=='ar' ? 'التسجيل كمستثمر' : 'Join as Investor'}</h1>
                    </div>

                    <div style={{
                        width: 'auto',
                        textAlign: lang=='ar'?'right':'left',
                        margin: '2rem 0 2rem 0',
                        padding: '0.5rem 0 0.5rem 0'
                    }}>
                    <div className="contract-type-selection" style={{margin: '1rem 0', display: 'flex', gap: '2rem', alignItems: 'center'}}>
                        <label style={{display: 'flex', alignItems: 'center', gap: '0.5rem', fontWeight: 500, fontSize: '1rem', color: '#073491'}}>
                            <input
                                type="radio"
                                name="contractType"
                                value="sale"
                                checked={contractType === "1"}
                                onChange={() => setContractType("1")}
                                style={{accentColor: '#073491'}}
                            />
                            {t('contract_type_sale') || 'عقد بيع'}
                        </label>
                        <label style={{display: 'flex', alignItems: 'center', gap: '0.5rem', fontWeight: 500, fontSize: '1rem', color: '#073491'}}>
                            <input
                                type="radio"
                                name="contractType"
                                value="rental"
                                checked={contractType === "2"}
                                onChange={() => setContractType("2")}
                                style={{accentColor: '#073491'}}
                            />
                            {t('contract_type_rental') || 'عقد استأجار'}
                        </label>
                    </div>
                    <div className='d-flex justify-content-center'>
                        <a
                            href="#"
                            style={{
                                color: ' #073491',
                                fontWeight: 600,
                                textDecoration: 'underline',
                                cursor: 'pointer',
                                fontSize: 16,
                                padding: '12px 32px',
                                borderRadius: 10,
                                border: '1.5px solid #073491',
                                background: '#f7faf7',
                                display: 'inline-block',
                                boxShadow: '0 2px 8px rgba(56,142,60,0.08)',
                                margin: '0.5rem 0'
                            }}
                            onClick={e => {
                                e.preventDefault();
                                isMobile? openPdfInNewTab(false) : openPdfDraft();
                            }}
                        >
                        {t('contract_draft_pdf')}
                        </a>
                    </div>

                    </div>
                    <div className="join-as-driver-form">
                        <form className="main-form" onSubmit={handleSubmit}>
                            <div className="main-form-description">
                                <p>{t('investor_info')}</p>
                            </div>
                            <div className="form-fields">
                                <div className="field-group-items">
                                    <div className="field-group-name">
                                        <label>{t('first_name')}</label>
                                        <input
                                            type="text"
                                            name="first_name"
                                            value={formData.first_name}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('first_name')}
                                        />
                                        {errors.first_name && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.first_name}</div>}
                                    </div>
                                    <div className="field-group-name">
                                        <label>{t('father_name')}</label>
                                        <input
                                            type="text"
                                            name="father_name"
                                            value={formData.father_name}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('father_name')}
                                        />
                                        {errors.father_name && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.father_name}</div>}
                                    </div>
                                </div>
                                <div className="field-group-items">
                                    <div className="field-group-name">
                                        <label>{t('grandfather_name')}</label>
                                        <input
                                            type="text"
                                            name="grandfather_name"
                                            value={formData.grandfather_name}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('grandfather_name')}
                                        />
                                        {errors.grandfather_name && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.grandfather_name}</div>}
                                    </div>
                                    <div className="field-group-name">
                                        <label>{t('family_name')}</label>
                                        <input
                                            type="text"
                                            name="family_name"
                                            value={formData.family_name}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('family_name')}
                                        />
                                        {errors.family_name && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.family_name}</div>}
                                    </div>
                                </div>
                                <div className="field-group-items">
                                    <div className="field-group-name">
                                        <label>{t('national_id')}</label>
                                        <input
                                            type="text"
                                            name="national_id"
                                            value={formData.national_id}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('national_id')}
                                        />
                                        {errors.national_id && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.national_id}</div>}
                                    </div>
                                    <div className="field-group-name">
                                        <label>{t('birth_date')}</label>
                                        <input
                                            type="date"
                                            name="birth_date"
                                            value={formData.birth_date}
                                            onChange={handleChange}
                                            className="input-field"
                                            max={new Date(new Date().setFullYear(new Date().getFullYear() - 17)).toISOString().split('T')[0]}
                                            required
                                            placeholder={t('birth_date')}
                                            dir={lang === 'ar' ? 'rtl' : 'ltr'}
                                        />
                                        {errors.birth_date && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.birth_date}</div>}
                                    </div>
                                </div>
                                <div className="field-group-items">
                                    <div className="field-group-name">
                                        <label>{t('phone_number')}</label>
                                        <PhoneInput
                                            className="input-field"
                                            name="phone"
                                            value={formData.phone}
                                            onChange={MobileInputValueChanged}
                                            required={true}
                                            placeholder={t('phone_number')}
                                        />
                                        {errors.phone && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.phone}</div>}
                                    </div>
                                    <div className="field-group-name">
                                        <label>{t('email')}</label>
                                        <input
                                            type="email"
                                            name="email"
                                            value={formData.email}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('email')}
                                        />
                                        {errors.email && <div style={{color:'#d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.email}</div>}
                                    </div>
                                </div>
                                <div className="field-group-items">
                                    <div className="field-group-name">
                                        <label>{t('region')}</label>
                                        <input
                                            type="text"
                                            name="region"
                                            value={formData.region}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('region')}
                                        />
                                        {errors.region && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.region}</div>}
                                    </div>
                                </div>
                                <div className="field-group-items">
                                    <div className="field-group-name" style={{width: '100%'}}>
                                        <label>{t('amount')}</label>
                                        <input
                                            type="number"
                                            name="amount"
                                            value={formData.amount}
                                            onChange={handleChange}
                                            className="input-field"
                                            required
                                            placeholder={t('amount')}
                                        />
                                        {errors.amount && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.amount}</div>}
                                    </div>
                                </div>
                                <div>
                                    <div className="form-agreement">
                                        <input type="checkbox" id="terms" name="terms" checked={isAgreed} onChange={(e) => setIsAgreed(e.target.checked)} />
                                        <label htmlFor="terms" className='px-2'> {t('agree_to')} <span>{t('terms_conditions')}</span></label>
                                        {errors.isAgreed && <div style={{color:' #d32f2f', fontSize:'0.9em', marginTop:2}}>{errors.isAgreed}</div>}
                                    </div>
                                    <div className="form-actions" style={{display: 'flex', gap: '1rem', alignItems: 'center'}}>
                                        {!nafathSigned ? (
                                            <>
                                                <button
                                                    type="button"
                                                    className="btn btn-outline-success"
                                                    style={{
                                                        minWidth: 120,
                                                        padding: '10px 24px',
                                                        fontWeight: 600,
                                                        fontSize: '1rem',
                                                        borderRadius: '8px',
                                                        background: '#fff',
                                                        color: '#073491',
                                                        border: '2px solid #073491',
                                                        boxShadow: '0 1px 4px rgba(0,0,0,0.08)',
                                                        transition: 'background 0.2s, color 0.2s'
                                                    }}
                                                    onClick={fillContractWithClientData}
                                                >
                                                    {t('view_contract') || 'عرض العقد'}
                                                </button>
                                            </>
                                        ) : (
                                            <button
                                                type="submit"
                                                className="btn btn-submit"
                                                disabled={!isAgreed}
                                                style={{
                                                    minWidth: 120,
                                                    padding: '10px 24px',
                                                    fontWeight: 600,
                                                    fontSize: '1rem',
                                                    borderRadius: '8px',
                                                    background: '#073491',
                                                    color: '#fff',
                                                    border: 'none',
                                                    boxShadow: '0 1px 4px rgba(0,0,0,0.08)',
                                                    transition: 'background 0.2s'
                                                }}
                                            >
                                                {t('submit')}
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
                <ScrollToTop />
            </div>
        </section>
  )
}

export default TsahelPage
